    if (data_p->pdu_type == NR_RRC_PDU_TYPE_SCCH)
    {
        if (data_p->choice == 1)
            return stat_packet(stat_data, data_p->message_type, nr_rrc_scch_c1_strings, 0);
        if (data_p->choice == 2)
            return stat_packet(stat_data, data_p->message_type + 8, nr_rrc_scch_c2_strings, 0);
